#!/usr/bin/env python3
"""A8 ApexLight. Byte-identical to BASE on both STLs after removing at most one
'; generated by ... on <date>' stamp line from each file.

usage: a8_apexlight.py BASE_DIR CAND_DIR [--json out.json]
"""
import argparse
import hashlib
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import scg_common as S

S.pin_sfg()

STAMP = re.compile(rb"^; generated by .+ on \d{4}-\d{2}-\d{2}.*\r?$")


def norm(path: str) -> tuple[bytes, int]:
    lines = open(path, "rb").read().split(b"\n")
    hits = [i for i, line in enumerate(lines) if STAMP.match(line)]
    if len(hits) > 1:
        raise SystemExit("more than one generated-by date line in %s" % path)
    body = b"\n".join(line for i, line in enumerate(lines) if i not in hits)
    return body, len(hits)


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("base_dir")
    ap.add_argument("cand_dir")
    ap.add_argument("--json")
    args = ap.parse_args()
    fails = []
    measured = {}
    parts = []
    for key, name in S.LIGHT.items():
        cand_b, cand_n = norm(S.gcode(args.cand_dir, name))
        base_b, base_n = norm(S.gcode(args.base_dir, name))
        first = None
        if cand_b != base_b:
            first = next((i for i in range(min(len(cand_b), len(base_b))) if cand_b[i] != base_b[i]),
                         min(len(cand_b), len(base_b)))
            fails.append("%s differs at normalized byte %d (cand %d bytes, base %d)" % (
                key, first, len(cand_b), len(base_b)))
        measured[key] = {
            "stamp_lines": [cand_n, base_n], "first_diff_byte": first,
            "cand_sha256": hashlib.sha256(cand_b).hexdigest(),
            "base_sha256": hashlib.sha256(base_b).hexdigest(),
            "cand_bytes": len(cand_b), "base_bytes": len(base_b),
        }
        parts.append(("%s_diff_byte" % key, -1 if first is None else first))
    status = "FAIL" if fails else "PASS"
    rep = {"gate": "A8 apexlight", "result": status, "failures": fails, "measured": measured}
    S.emit(status, "A8", parts, rep, args.json)


if __name__ == "__main__":
    main()
